StructuredTextModel.Text:
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			UV Data - Wedeco
//	CREATOR:		Helgevold - William Veim                                                                                                                                                                                                                                                              
// REQ: 			Wedeco UV system - ModbusTCP option                                                                                                                                                                                                                                                                                                                          
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION		DATE				SIGN						DESCRIPTION                                                                                                                                                                                                                                 
//	1.0.0				2026-07-14		William Veim			Initial release              
//
//===============================================================================================================================

 (*************************************************************************
 *	CONGIURING MODBUS REQUEST
 *************************************************************************)
 
MTCP_Request[0].Enable :=									TRUE;
MTCP_Request[0].NodeAdr :=	 							1;
MTCP_Request[0].FunctionCode := 					eFun#Fn04_ReadInputRegisters;
MTCP_Request[0].Read.StartAddressLocal :=		0;
MTCP_Request[0].Read.StartAddressRemote := 	0;
MTCP_Request[0].Read.Count := 						60;

MTCP_Request[1].Enable :=									TRUE;
MTCP_Request[1].NodeAdr := 							1;
MTCP_Request[1].FunctionCode := 					eFun#Fn16_WriteMultipleRegisters;
MTCP_Request[1].Write.StartAddressLocal := 	 0;
MTCP_Request[1].Write.StartAddressRemote :=  0;
MTCP_Request[1].Write.Count := 						  2; 

FB_MTCP(Enable:=						TRUE, 
				IPAddress:=					Cfg_IPAdr, 
				PortNo:=						Cfg_PortNo, 
				UpdateRate:=				Cfg_UpdateRate, 
				NodeTimeOut:=			ADD_TIME(In1:=Cfg_UpdateRate, In2:=Cfg_UpdateRate), 
				Status=>						MTCP_Status, 
				RequestCycleDone=>	MTCP_ReqCycleDone, 
				RequestCycleTime=>	MTCP_ReqCycleTime, 
				Error=>						MTCP_Error, 
				ErrorID=>					MTCP_ErrorID, 
				ErrorIDEx=>					MTCP_ErrorID_Ex, 
				ErrorRequestNO=>		MTCP_ErrorRequestNO, 
				ModbusError=>			MTCP_ModbusError, 
				Requests:=					MTCP_Request, 
				Coils:=							MTCP_Coils, 
				DiscreteInputs:=			MTCP_DiscreteInputs, 
				InputRegisters:=			MTCP_InputRegister, 
				HoldingRegisters:=		MTCP_HoldingRegister);

(*************************************************************************
 *	INTERNAL VARIABLE CONTROL
 *************************************************************************)
 
Ext_UV_Data.EXT_General.LocationIndex[0]:=Cfg_MainLocation; //First index / main location is forced; remaining tree optional can be set in SCADA
RE_SecPulse(Clk:=Get1sClk());

FB_Watchdog(ENS:=TRUE, 
						Cfg_Type:=0, 
						Inp_Number:=WORD_TO_ULINT(MTCP_InputRegister[58]));
						
//Communication state
IF MTCP_Request[0].Status.Success AND NOT MTCP_Request[0].Status.Error 
	AND MTCP_Request[1].Status.Success AND NOT MTCP_Request[1].Status.Error 
	AND NOT FB_Watchdog.Sts_Timeout THEN
	
	Wrk_CommState:=TRUE;
ELSE
	Wrk_CommState:=FALSE;
END_IF;

(*************************************************************************
 *	UPDATING VARIABELS
 *************************************************************************)

CASE  WORD_TO_UINT(MTCP_InputRegister[1]) OF
	
	0:
		Ext_UV_Data.EXT_Operator.Actual_State:=	'Initialising';
		
	1:
		Ext_UV_Data.EXT_Operator.Actual_State:=	'Startup';
		
	2:
		Ext_UV_Data.EXT_Operator.Actual_State:=	'Warmup';
		
	3:
		Ext_UV_Data.EXT_Operator.Actual_State:=	'System running';
		
	4:
		Ext_UV_Data.EXT_Operator.Actual_State:=	'Warning';
		
	5:
		Ext_UV_Data.EXT_Operator.Actual_State:=	'Alarm';
		
	6:
		Ext_UV_Data.EXT_Operator.Actual_State:=	'Shutdown';
		
	7:
		Ext_UV_Data.EXT_Operator.Actual_State:=	'Standby';
		
	8:
		Ext_UV_Data.EXT_Operator.Actual_State:=	'Service';
	
END_CASE;

Ext_UV_Data.EXT_Operator.LocalOperation:=			TestABitN(In:=MTCP_InputRegister[3], Pos:=11);
Ext_UV_Data.EXT_Operator.CountDown:= 				WORD_TO_INT(MTCP_InputRegister[24]);
Ext_UV_Data.EXT_Operator.DoseLevel:= 				HE_WORD_CheckValid(Word_1:=MTCP_InputRegister[5], UnvalidValue:=16#FFFF) / 10; 	// mJ/cm2
Ext_UV_Data.EXT_Operator.FlowRate:=					HE_WORD_CheckValid(Word_1:=MTCP_InputRegister[4], UnvalidValue:=16#FFFF) / 10; 	// m3/h
Ext_UV_Data.EXT_Operator.IntensityLevel:=			HE_WORD_CheckValid(Word_1:=MTCP_InputRegister[9], UnvalidValue:=16#FFFF) / 10; 	// W/m2
Ext_UV_Data.EXT_Operator.PowerLevel:=				HE_WORD_CheckValid(Word_1:=MTCP_InputRegister[18], UnvalidValue:=16#FFFF); 		// %
Ext_UV_Data.EXT_Operator.Temperature:=				HE_WORD_CheckValid(Word_1:=MTCP_InputRegister[24], UnvalidValue:=16#FFFF) / 10 - 273.15;

Ext_UV_Data.EXT_Statistics.OperatingTime:=			WORD_TO_LINT(MTCP_InputRegister[20]);
Ext_UV_Data.EXT_Statistics.PowerConsumption:=	HE_WORD_CheckValid(Word_1:=MTCP_InputRegister[25], UnvalidValue:=16#FFFF) / 100;
Ext_UV_Data.EXT_Statistics.WipingCycles:=			WORD_TO_LINT(MTCP_InputRegister[22]);
Ext_UV_Data.EXT_Statistics.StartCycles:=	 				WORD_TO_LINT(MTCP_InputRegister[19]);

//OUTPUT DATA
OutABit(InOut:=MTCP_HoldingRegister[3], Pos:=0, BitVal:=Ext_UV_Data.EXT_Operator.SystemStart AND ((Cfg_Interlock = 1 OR Cfg_Interlock = 2) AND NOT Inp_Interlock)); 	//Remote ON
OutABit(InOut:=MTCP_HoldingRegister[3], Pos:=1, BitVal:=FALSE);		//Full power mode
OutABit(InOut:=MTCP_HoldingRegister[3], Pos:=2, BitVal:=FALSE);		//Auxillary relay control
OutABit(InOut:=MTCP_HoldingRegister[3], Pos:=3, BitVal:=(Cfg_Interlock = 2 AND Inp_Interlock));		//Shutdown
OutABit(InOut:=MTCP_HoldingRegister[3], Pos:=4, BitVal:=FALSE);		//Sensor hold

IF Cfg_FlowInUse THEN
	MTCP_InputRegister[1]:=REAL_TO_WORD(Inp_Flowrate);
END_IF;

//Increment heartbeat
IF RE_SecPulse.Q THEN
	MTCP_InputRegister[0]:= INT_TO_WORD(WORD_TO_INT(MTCP_InputRegister[0]) + 1);
END_IF;

(*************************************************************************
 *	ALARM/FAULT STATUS
 *************************************************************************)

Wrk_State[1]:=NOT Wrk_CommState;
Wrk_Suffix[1]:='Communication fault';
Wrk_State[2]:=TestABit(In:=MTCP_InputRegister[2], Pos:=0);
Wrk_Suffix[2]:='Water level low';
Wrk_State[3]:=TestABit(In:=MTCP_InputRegister[2], Pos:=1) OR TestABit(In:=MTCP_InputRegister[2], Pos:=2) OR TestABit(In:=MTCP_InputRegister[3], Pos:=5) OR TestABit(In:=MTCP_InputRegister[3], Pos:=6);
Wrk_Suffix[3]:='Cabinet high temperature';
Wrk_State[4]:=TestABit(In:=MTCP_InputRegister[2], Pos:=3) OR TestABit(In:=MTCP_InputRegister[2], Pos:=4) OR TestABit(In:=MTCP_InputRegister[2], Pos:=5);
Wrk_Suffix[4]:='Flow rate fault';
Wrk_State[5]:=TestABit(In:=MTCP_InputRegister[2], Pos:=6) OR TestABit(In:=MTCP_InputRegister[2], Pos:=7) OR TestABit(In:=MTCP_InputRegister[2], Pos:=8) OR TestABit(In:=MTCP_InputRegister[3], Pos:=2);
Wrk_Suffix[5]:='UVT sensor fault';
Wrk_State[6]:=TestABit(In:=MTCP_InputRegister[2], Pos:=9) OR TestABit(In:=MTCP_InputRegister[2], Pos:=10) OR TestABit(In:=MTCP_InputRegister[2], Pos:=11);
Wrk_Suffix[6]:='Internal communication fault';
Wrk_State[7]:=TestABit(In:=MTCP_InputRegister[3], Pos:=1);
Wrk_Suffix[7]:='Flow warning';
Wrk_State[8]:=TestABit(In:=MTCP_InputRegister[3], Pos:=3);
Wrk_Suffix[8]:='UV is adjusted';
Wrk_State[9]:=TestABit(In:=MTCP_InputRegister[3], Pos:=4);
Wrk_Suffix[9]:='Lamp lifte time expired';
Wrk_State[10]:=TestABit(In:=MTCP_InputRegister[3], Pos:=7);
Wrk_Suffix[10]:='Cooling failure';
Wrk_State[11]:=Inp_Interlock AND Cfg_Interlock > 0;
Wrk_Suffix[11]:='Interlocked';
Wrk_State[12]:=FALSE;
Wrk_Suffix[12]:='';

(*************************************************************************
 *	EXCECUTING LOGIC BLOCK
 *************************************************************************)

FB_Data_Logic(Ext_Alarm:=						Ext_UV_Data.EXT_Alarm, 
						EXT_Engineering:=			Ext_UV_Data.EXT_Engineering, 
						Ext_General:=					Ext_UV_Data.EXT_General, 
						Int_Alarm:=						Int_Alarm, 
						Inp_StateState:=				Wrk_State, 
						Inp_StateSuffix:=				Wrk_Suffix, 
						Inp_AlmSuppressDesc:=	Cfg_AlmSuppressDesc, 
						Inp_AlmSuppress:=			Inp_AlmSuppress);

(*************************************************************************
 *	UPDATING OUTPUT
 *************************************************************************)
 
 //BLOCK
 Sts_Alarm:= FB_Data_Logic.Sts_AlarmTriggered;
 
 //STRUCTURE
 Ext_UV_Data.EXT_General.Connected_ControlCabinet:=	Cfg_ConnCab;
 Ext_UV_Data.EXT_General.Controlled_FromController:=	Cfg_ControllerName;
 Ext_UV_Data.EXT_General.Process_TAG:=							Cfg_ProcessTAG;
